<?php foreach($albums as $a): ?><div id="album-<?= e($a['slug']) ?>" class="card card-border-merah" data-album data-era="<?= e($a['era']) ?>" data-tipe="<?= e($a['type']) ?>"><div class="album-cover"><img src="<?= e($a['cover_url']??'images/album-cover.jpg') ?>" alt="<?= e($a['title']) ?>"></div><div class="album-head"><div><h3 class="berita-judul"><?= e($a['title']) ?></h3><p class="lagu-artis"><?= e(date_part($a['release_date'],'Y')) ?> · <?= (int)($a['total_tracks']??count($a['tracks'])) ?> Lagu</p></div><span class="pill"><?= e(ALBUM_TYPES[$a['type']]??$a['type']) ?></span></div><ul class="tracklist"><?php foreach($a['tracks'] as $t): ?><li><?= (int)$t['track_no'] ?>. <?= e($t['title']) ?></li><?php endforeach; ?></ul><a class="btn btn-merah lebar" href="#album-<?= e($a['slug']) ?>">Lihat Album</a></div><?php endforeach; ?>
<p id="album-kosong" class="pesan-kosong" hidden>Tidak ada album yang sesuai dengan filter.</p>
